@push('scripts')<script>
(function(){const course=document.getElementById('public-sim-course'),mode=document.getElementById('public-sim-mode'),lottery=document.getElementById('public-sim-lottery'),manual=document.getElementById('public-sim-manual'),box=document.getElementById('public-sim-subjects'),total=document.getElementById('public-sim-total'),warn=document.getElementById('public-sim-warning'),old=@json(old('quantities',[]));let seq=0;
function toggle(){lottery.hidden=mode.value!=='lottery';manual.hidden=mode.value!=='manual';}function inputs(){return [...box.querySelectorAll('input[data-qty]')];}function sum(){return inputs().reduce((n,i)=>n+(Number(i.value)||0),0);}function update(){let n=sum();total.textContent=n+' questões';warn.hidden=n<=120;warn.textContent=n>120?'Limite máximo de 120 questões ultrapassado.':'';for(let i of inputs()){let step=i.closest('.public-sim-stepper');step.querySelector('[data-step="minus"]').disabled=Number(i.value)<=0;step.querySelector('[data-step="plus"]').disabled=Number(i.value)>=Math.min(120,Number(i.dataset.available)||0)||n>=120;}}function set(i,n){let other=sum()-(Number(i.value)||0);i.value=Math.max(0,Math.min(Math.min(120,Number(i.dataset.available)||0),120-other,Math.floor(Number(n)||0)));update();}
async function refresh(){let n=++seq;box.textContent='Carregando disciplinas...';try{let res=await fetch(@json(route('admin.public-simulations.scope'))+'?course_id='+encodeURIComponent(course.value),{headers:{Accept:'application/json'},credentials:'same-origin'});if(!res.ok)throw Error('Falha ao consultar disciplinas');let data=await res.json();if(n!==seq)return;box.replaceChildren();if(!data.subjects.length){box.textContent='Nenhuma disciplina ativa neste curso.';return;}for(let s of data.subjects){let row=document.createElement('div');row.className='public-sim-distribution-row';let label=document.createElement('div');let b=document.createElement('strong');b.textContent=s.name;let info=document.createElement('small');info.className='d-block text-muted';info.textContent=s.available+' disponíveis';label.append(b,info);let step=document.createElement('div');step.className='public-sim-stepper';let input=document.createElement('input');input.type='number';input.min=0;input.max=Math.min(120,s.available);input.name='quantities['+s.id+']';input.dataset.qty='1';input.dataset.available=s.available;input.value=0;input.setAttribute('aria-label','Quantidade de '+s.name);let minus=document.createElement('button'),plus=document.createElement('button');minus.type=plus.type='button';minus.textContent='−';plus.textContent='+';minus.dataset.step='minus';plus.dataset.step='plus';minus.addEventListener('click',()=>set(input,Number(input.value)-1));plus.addEventListener('click',()=>set(input,Number(input.value)+1));input.addEventListener('change',()=>set(input,input.value));input.addEventListener('input',update);step.append(minus,input,plus);row.append(label,step);box.append(row);if(Object.prototype.hasOwnProperty.call(old,String(s.id)))set(input,old[String(s.id)]);}update();}catch(e){if(n===seq)box.textContent=e.message;}}
course.addEventListener('change',refresh);mode.addEventListener('change',toggle);toggle();refresh();})();
</script>
@endpush
